mod = 10**9 + 7
def ksm (a, b, mod):
    res = 1
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res
t = int(input())
for _ in range(t):
    n = int(input())
    fz = n * (n + 1) % mod * (n + 2) % mod
    fm = 6
    inv_fm = ksm(fm, mod - 2, mod)
    comb = fz * inv_fm % mod
    p2 = ksm(2, n - 1, mod)
    print(comb * p2 % mod)

```

### java
```java
import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;

    public static long ksm(long a, long b, long mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = res * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt();
            long fz = (long) n * (n + 1) % MOD * (n + 2) % MOD;
            long fm = 6;
            long inv_fm = ksm(fm, MOD - 2, MOD);
            long comb = fz * inv_fm % MOD;
            long p2 = ksm(2, n - 1, MOD);
            System.out.println(comb * p2 % MOD);
        }
        scanner.close();
    }
}
```
